pub(crate) fn a_buffer_name(name: &str, args: &[Ty]) -> bool {
    let base = base_name(name);
    if base == "String" || base == "Bytes" || base == "Mapped" { return true; }
    if (base == "Vec" || base == "List") && !args.is_empty() { return names_u8(unsafe { nikaia_std::proven::read(&args, (0) as usize) }); }
    false
}

pub(crate) fn names_u8(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, .. } => base_name(name) == "u8",
        _ => false,
    }
}

pub(crate) fn keep_words(keep: &KeepAt) -> &'static str {
    match keep {
        KeepAt::Param => "in the caller's keep, because views of it leave this function",
        KeepAt::Frame => "in a keep of this function until it returns, because something outside the loop or block keeps views of it",
        KeepAt::Local(_) => "in a keep beside the call, as long as what the call hands back",
        KeepAt::Task => "in a keep the task carries with it (one count per task, not per view)",
        KeepAt::Element(_) => "in a keep of its own, held by each view kept of it, because what keeps the views drops entries while the loop goes on",
    }
}

pub(crate) fn goes_in_the_callers_keep(keep: &KeepAt) -> bool { matches!(keep, KeepAt::Param) }

pub(crate) fn lives_in_a_local_keep(keep: &KeepAt) -> bool { matches!(keep, KeepAt::Local(_)) }

pub(crate) fn an_argument(key: &str) -> String {
    let parts: Vec<&str> = key.split('#').collect::<Vec<_>>();
    if parts.len() < 2 { return format!("what `{}` reads", key); }
    let place = nikaia_std::index::or(text::parse_i64(*unsafe { nikaia_std::proven::read(&parts, (1) as usize) }), || 0) + 1;
    format!("argument {} made in the call to `{}`", place, *unsafe { nikaia_std::proven::read(&parts, (0) as usize) })
}

